 import React, { useEffect, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useToast } from '../contexts/ToastContext'
import { completePayment } from '../services/paymentService'

export default function PaymentSuccess() {
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [loading, setLoading] = useState(true)
    const [communityId, setCommunityId] = useState(null)
    const [paymentId, setPaymentId] = useState(null)
    const [userId, setUserId] = useState(null)

    useEffect(() => {
        const params = new URLSearchParams(window.location.search)
        const paymentId = params.get('m_payment_id')
        const communityId = params.get('custom_str1')
        const userId = params.get('custom_str2')
        
        setCommunityId(communityId)
        setPaymentId(paymentId)
        setUserId(userId)

        if (paymentId && communityId && userId) {
            completePaymentAndJoin(paymentId, communityId, userId)
        } else {
            setLoading(false)
        }
    }, [])

    const completePaymentAndJoin = async (paymentId, communityId, userId) => {
        try {
            const result = await completePayment(paymentId, communityId, userId)
            
            if (result.success) {
                showToast('✅ Welcome to the community!', 'success')
                setTimeout(() => {
                    navigate(`/community/${communityId}`)
                }, 2000)
            } else {
                showToast('Failed to join community: ' + result.error, 'error')
                navigate('/community')
            }
        } catch (error) {
            console.error('Error completing payment:', error)
            showToast('Payment verification failed', 'error')
            navigate('/community')
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-xl p-8 max-w-md w-full text-center">
                <div className="text-6xl mb-4">✅</div>
                <h1 className="text-2xl font-bold text-gray-800">Payment Successful!</h1>
                <p className="text-gray-500 mt-2">Thank you for joining the community.</p>
                {loading ? (
                    <p className="text-sm text-gray-400 mt-4">Adding you to the community...</p>
                ) : (
                    <Link 
                        to={communityId ? `/community/${communityId}` : '/community'}
                        className="inline-block mt-6 bg-green-600 text-white px-6 py-3 rounded-lg hover:bg-green-700 transition"
                    >
                        Go to Community
                    </Link>
                )}
            </div>
        </div>
    )
}
